import{z as k,x as p,o as t,c as d,q as o,j as E,D as n,d as r,s,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"参数化复杂性 FPT","description":"","frontmatter":{"title":"参数化复杂性 FPT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fpt-parameterized.md","filePath":"cs/fpt-parameterized.md","lastUpdated":1791063341000}'),P={name:"cs/fpt-parameterized.md"};function A(T,a,F,f,m,B){const l=p("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="参数化复杂性-fpt" tabindex="-1">参数化复杂性 FPT <a class="header-anchor" href="#参数化复杂性-fpt" aria-label="Permalink to &quot;参数化复杂性 FPT&quot;">​</a></h1><div class="epigraph"><p>把参数 $k$ 从输入长度 $n$ 里拆出来：$f(k)n^{O(1)}$ 为 FPT；若必须 $n^{g(k)}$，则停在 XP 或 W 层级，顶点覆盖与团因此分家。</p><footer>—— 据 Downey and Fellows, Parameterized Complexity；Cygan et al., Parameterized Algorithms 整理</footer></div><p>上一课<a href="/cs/circuit-complexity">电路</a> 仍对 \\(n\\) 最坏。主干 NPC 把顶点覆盖与团捆在一起。缺口是<strong>参数</strong>：覆盖大小 \\(k\\) 小时，覆盖有 \\(1.28^k n\\) 一类算法，团没有已知的 \\(n^{o(k)}\\)。FPT vs W[1]。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>参数化问题 \\((x,k)\\)。FPT：时间 \\(f(k)|x|^{O(1)}\\)，\\(f\\) 任意可计算（通常指数）。核：多项式时间压到 \\(g(k)\\) 规模，再蛮力。顶点覆盖：搜两边或核 \\(2k\\)。团、独立集对参数解大小是 W[1] 完全：相信不在 FPT。W 层级用短路电路或权 \\(k\\) 的 SAT 切片定义，本课要形状不写完全性证明。</p><p>XP：\\(n^{g(k)}\\)，包含 FPT。FPT \\(\\neq\\) XP 若时间层级一类假设。ETH（指数时间假设）把 \\(2^{o(n)}\\) 的 3SAT 排除，用来钉 FPT 的 \\(f(k)\\) 底。</p><h3 id="不是「-很小就多项式」" tabindex="-1">不是「\\(k\\) 很小就多项式」 <a class="header-anchor" href="#不是「-很小就多项式」" aria-label="Permalink to &quot;不是「$k$ 很小就多项式」&quot;">​</a></h3><p>\\(n^k\\) 当 \\(k=\\log n\\) 已超多项式。FPT 要求 \\(n\\) 的指数与 \\(k\\) 无关。把 \\(k\\) 取成 \\(n\\) 就退回古典。<span class="marginnote">初学者容易把 \\(n^k\\) 当成 FPT——\\(k=3\\) 时确实跑得飞快；但 \\(k=60\\) 时哪怕 \\(n\\) 只有 1000，\\(n^k\\) 也早已算不动，因为 \\(n\\) 的指数跟着 \\(k\\) 一起涨。FPT 把难的部分全部塞进 \\(k\\) 的函数 \\(f(k)\\)：\\(k=10\\) 时哪怕 \\(f(k)=2^k=1024\\) 也只是千倍常数，\\(n\\) 那边保持多项式，这才是 FPT。</span></p><p><span class="marginnote">Downey–Fellows 开创。Cygan 等是算法书。本课不把树宽算法写完，点名：树宽 \\(w\\) 时许多问题 \\(2^{O(w)}n\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对顶点覆盖给搜树或核的思路。对团说明为何蛮力 \\(n^k\\) 停在 XP。声明：同一古典 NPC 问题，换参数（解大小、树宽、删除数）可进 FPT 或 W 难。不要对所有 NPC 宣称「参数化之后就好」。</p>',11)),(t(),E(i,null,{default:n(()=>[s(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NPC%5B%22%E5%8F%A4%E5%85%B8%20NP%20%E5%AE%8C%E5%85%A8%22%5D%20--%3E%20PAR%5B%22%E9%80%89%E5%AE%9A%E5%8F%82%E6%95%B0%20k%22%5D%0A%20%20PAR%20--%3E%20FPT%5B%22f(k)%20n%5EO(1)%22%5D%0A%20%20PAR%20--%3E%20W1%5B%22W1%20%E5%AE%8C%E5%85%A8%20%2F%20%E9%9D%9E%20FPT%20%E4%BF%A1%E5%BF%B5%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"FPT 把组合爆炸关进 \\(k\\)。实践：编译、生物网络里 \\(k\\) 真小才有意义。W[1] 完全是参数世界的 SAT。与近似、随机正交：一个问题可以 FPT 但不可近似，或反之。",-1)),a[5]||(a[5]=e("p",null,"核大小下界（多项式核是否存在）是另一层，本课点名。",-1)),a[6]||(a[6]=e("p",null,"核是 FPT 的证书：压到 \\(g(k)\\) 再 \\(2^{g(k)}\\) 蛮力仍 FPT。多项式核是否存在另有下界技术（或门）。树宽 \\(w\\) 时，许多 MSO 性质 \\(f(w)n\\)，Courcelle，点名。把 \\(k\\) 取成解大小，顶点覆盖与团分家——同一 NPC 标签，参数化后不是一类。",-1)),(t(),E(i,null,{default:n(()=>[s(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%90%8C%E4%B8%80%E5%8F%A4%E5%85%B8%20NPC%20%E9%97%AE%E9%A2%98%22%5D%20--%3E%20VC%5B%22%E5%8F%82%E6%95%B0%E5%8F%96%E8%A7%A3%E5%A4%A7%E5%B0%8F%20k%22%5D%0A%20%20IN%20--%3E%20TW%5B%22%E5%8F%82%E6%95%B0%E5%8F%96%E6%A0%91%E5%AE%BD%20w%22%5D%0A%20%20VC%20--%3E%20VCP%5B%22%E9%A1%B6%E7%82%B9%E8%A6%86%E7%9B%96%EF%BC%9A1.28%5Ek%20n%20%E6%9C%89%E7%AE%97%E6%B3%95%22%5D%0A%20%20VC%20--%3E%20CLQ%5B%22%E5%9B%A2%EF%BC%9AW1%20%E5%AE%8C%E5%85%A8%EF%BC%8C%E6%97%A0%E5%B7%B2%E7%9F%A5%20n%5Eo(k)%22%5D%0A%20%20TW%20--%3E%20TWZ%5B%22%E6%A0%91%E5%AE%BD%20w%EF%BC%9A%E8%AE%B8%E5%A4%9A%E9%97%AE%E9%A2%98%202%5EO(w)%20n%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">这张图回答的问题是：同一个问题的「难」为什么会随参数选择而改变。顶点覆盖与团在古典世界里都是 NP 完全，但把参数换成解的大小之后，前者进 FPT、后者停在 W[1]——「参数化之后难不难」是问题加参数这对组合的属性，不是问题名字的属性。</span></p><p><span class="marginnote">核化可以想象成考前划重点：先用多项式时间把题目里与答案无关的部分删掉，只留下规模不超过 \\(g(k)\\) 的「核」，再对这个小核死记硬背（蛮力枚举）。比如顶点覆盖压到 \\(2k\\) 个顶点的核，\\(k=20\\) 时核最多 40 个顶点，\\(2^{40}\\) 次枚举在现代机器上是秒级的事。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 W[1] 完全，不引入 MSO / Courcelle 全文。不把机器学习的超参当 \\(k\\)。后课默认：谈「\\(k\\) 小时」，先问 FPT 还是 \\(n^k\\)。下一课平均情形与单向函数。</p><p>FPT 要求 \\(n\\) 的指数与 \\(k\\) 脱钩；\\(n^k\\) 停在 XP。ETH 用来钉 \\(f(k)\\) 不能再降到 \\(2^{o(k)}\\) 一类。同一古典 NPC 问题换参数（树宽 vs 解大小）可进 FPT 或 W 难。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FPT \\(= f(k)n^{O(1)}\\)；顶点覆盖典型，团对解大小不是。</li><li>W[1] 是参数化硬度；ETH 钉 \\(f(k)\\) 底。</li><li>参数选择决定类，不是问题名字决定。</li><li>出处：Downey and Fellows；Cygan et al.。</li></ul>',7))])}const u=k(P,[["render",A]]);export{h as __pageData,u as default};
